const callback = function(mutations) { 
  for (let mutation of mutations) {
    if (mutation.previousSibling.id === 'promo_code_input') {
          setTimeout(function(){
            window.location.reload(true);
          }, 2000);
    }
  }
};

const elementToWatch = document.querySelector('#billing_form');

const watcher = new MutationObserver(callback);
watcher.observe(elementToWatch, {
  childList: true,
  subtree: true
});

const field = document.querySelector('#promo_code_input');
field.dispatchEvent(new Event('input', { bubbles: true }));
field.dispatchEvent(new Event('change'));
field.dispatchEvent(new Event('keyup'));
field.dispatchEvent(new Event('blur'));
field.dispatchEvent(new Event('focus'));
document.querySelector('#submit_promo_button').click();
